cd /work/workspace/deliverable && python3 - <<'EOF'
import csv, json

def num(s): return float(s) if s.strip() else 0.0

tb = json.load(open('trial_balance_2026-03-31.json'))
ajes = json.load(open('adjusting_entries.json'))

feb = {}
for r in csv.DictReader(open('../documents/trial_balance_2026-02-28.csv')):
    feb[r['account'].split()[0]] = [num(r['debit']), num(r['credit'])]
gl = {}
for r in csv.DictReader(open('../documents/general_ledger_2026-03.csv')):
    k = r['account'].split()[0]
    gl.setdefault(k, [0.0, 0.0]); gl[k][0] += num(r['debit']); gl[k][1] += num(r['credit'])
rebuilt = {k: list(v) for k, v in feb.items()}
for k, v in gl.items():
    rebuilt.setdefault(k, [0.0, 0.0]); rebuilt[k][0] += v[0]; rebuilt[k][1] += v[1]
for e in ajes:
    for l in e['lines']:
        k = l['account'].split()[0]
        rebuilt.setdefault(k, [0.0, 0.0]); rebuilt[k][0] += l['debit']; rebuilt[k][1] += l['credit']

mm = []
for k, exp in tb['accounts'].items():
    got = rebuilt.get(k, [0.0, 0.0])
    if abs(got[0]-exp['debit']) > 1e-6 or abs(got[1]-exp['credit']) > 1e-6:
        mm.append((k, exp['debit'], exp['credit'], got[0], got[1]))
print('per-account mismatches:', mm or 'NONE')
td = sum(v['debit'] for v in tb['accounts'].values()); tc = sum(v['credit'] for v in tb['accounts'].values())
print('TB totals: D %.2f C %.2f diff %.2f' % (td, tc, td-tc))
inc = sum(v['credit']-v['debit'] for k, v in tb['accounts'].items() if k[0] in '456')
print('YTD net income: %.2f' % inc)
print('2100: %.2f Cr | 3100: %.2f Cr | 3200: %.2f Dr | 1000: %.2f Dr | 4000: %.2f Cr' % (
    tb['accounts']['2100']['credit'], tb['accounts']['3100']['credit'],
    tb['accounts']['3200']['debit'], tb['accounts']['1000']['debit'], tb['accounts']['4000']['credit']))
EOF

